1	/**
2	 * POST /api/jvto/send
3	 * { numberId, phone, message }
4	 * Sends a WhatsApp message from a specific WA number to a JVTO customer.
5	 */
6	import { NextRequest, NextResponse } from "next/server";
7	import { getSession } from "@/lib/auth";
8	import { db } from "@/lib/db";
9	import { getOrCreateWaClient, waitForConnected } from "@/lib/wa-client";
10	import { isJvtoPhone, normalizePhone } from "@/lib/jvto-utils";
11	
12	export async function POST(req: NextRequest) {
13	  const session = await getSession();
14	  if (!session || (!session.isJvto && session.role !== "ADMIN")) {
15	    return NextResponse.json({ error: "Forbidden" }, { status: 403 });
16	  }
17	
18	  const { numberId, phone, message } = await req.json();
19	
20	  if (!numberId || !phone || !message?.trim()) {
21	    return NextResponse.json({ error: "numberId, phone, and message required" }, { status: 400 });
22	  }
23	
24	  if (!isJvtoPhone(phone)) {
25	    return NextResponse.json({ error: "Not a JVTO customer phone" }, { status: 400 });
26	  }
27	
28	  const number = await db.waNumber.findUnique({
29	    where: { id: numberId },
30	    select: { id: true, userId: true, phoneNumber: true, label: true },
31	  });
32	  if (!number) return NextResponse.json({ error: "WA number not found" }, { status: 404 });
33	
34	  try {
35	    const client = await getOrCreateWaClient(numberId);
36	    if (client.status !== "connected") {
37	      const ok = await waitForConnected(client, 10_000);
38	      if (!ok) return NextResponse.json({ error: "WhatsApp is not connected" }, { status: 400 });
39	    }
40	
41	    await client.sendText(phone, message.trim());
42	
43	    // Save to MessageLog
44	    await db.messageLog.create({
45	      data: {
46	        numberId,
47	        direction: "OUT",
48	        toFrom: normalizePhone(phone),
49	        content: message.trim(),
50	        mediaType: null,
51	      },
52	    });
53	
54	    return NextResponse.json({ success: true });
55	  } catch (err) {
56	    console.error("[POST /api/jvto/send]", err);
57	    return NextResponse.json(
58	      { error: err instanceof Error ? err.message : "Failed to send" },
59	      { status: 500 }
60	    );
61	  }
62	}
